/**
 * The stations ADIF's hub can be asked about, for the station search.
 *
 * The hub has no list to search, and nothing on info.adif.es answers a
 * cross-origin request, so the list is baked in: stations.data.json is
 * generated by tools/build_adif_stations.py from Renfe's register of stations
 * (CC BY 4.0), mitren.app's list of Cercanías stations and the names ADIF's
 * own boards print. The names a board sends for its trains' stations are read
 * off the board itself (map.ts); this list only finds the station to open.
 *
 * Codes are ADIF's, five digits with the leading zero (`03100` is Jaén). The
 * hub's group names need all five; the boards drop the zero when naming a
 * station (`3100`), so both are read as the same code.
 */
import type { Place } from '../../model';
import data from './stations.data.json';

export interface AdifStation {
  code: string;
  name: string;
  /** Shorter forms, longest first. */
  names: string[];
  town: string;
  province: string;
  /** Everything a search may match on, folded. */
  haystack: string;
  foldedName: string;
}

export const TIME_ZONE = 'Europe/Madrid';

/** Where the list comes from, as the builder wrote it. */
export const STATIONS_SOURCE: string = data.source;

/** A code as the hub's group names want it: five digits. Anything else is left as it is. */
export function normalCode(code: string | number | null | undefined): string {
  const text = String(code ?? '').trim();
  return /^\d{1,5}$/.test(text) ? text.padStart(5, '0') : text;
}

/**
 * Case- and accent-insensitive form for matching. "Ñ" folds to "N" here,
 * which is what someone typing on a keyboard without one expects.
 */
export function fold(text: string | undefined | null): string {
  return String(text ?? '')
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();
}

let index: { stations: AdifStation[]; byCode: Map<string, AdifStation> } | undefined;

/** Built on first use rather than on import: fifteen hundred rows nobody may ask about. */
function getIndex(): NonNullable<typeof index> {
  if (index) return index;
  const stations = (data.stations as string[][]).map((row): AdifStation => {
    const [code = '', name = '', shorter = '', town = '', province = ''] = row;
    const names = shorter ? shorter.split('|') : [];
    return {
      code,
      name,
      names,
      town,
      province,
      haystack: fold([name, ...names, town, province, code].join(' ')),
      foldedName: fold(name),
    };
  });
  index = { stations, byCode: new Map(stations.map((station) => [station.code, station])) };
  return index;
}

export function allStations(): AdifStation[] {
  return getIndex().stations;
}

export function findStation(code: string | number | null | undefined): AdifStation | undefined {
  return getIndex().byCode.get(normalCode(code));
}

/** A station as a model Place, with its ladder of shorter names. */
export function stationPlace(station: AdifStation): Place {
  const place: Place = {
    id: `adif/${station.code}`,
    codes: { adif: station.code },
    name: station.name,
    country: 'es',
    timeZone: TIME_ZONE,
  };
  if (station.names.length) place.names = [...station.names];
  if (station.town) place.town = station.town;
  return place;
}

/**
 * Ranked matches for what someone typed: a station code, or words from the
 * name, its shorter forms, its town or its province, in any order and without
 * accents.
 */
export function searchStations(query: string, limit = 8): AdifStation[] {
  const q = fold(query);
  if (!q) return [];
  const words = q.split(' ');
  const first = words[0] ?? '';
  const numeric = /^\d+$/.test(q);
  const scored: [number, AdifStation][] = [];
  for (const station of getIndex().stations) {
    let score: number;
    if (numeric) {
      // A code typed without its leading zero still finds it.
      const typed = station.code.startsWith(q) ? station.code : station.code.replace(/^0+/, '');
      if (!typed.startsWith(q)) continue;
      score = typed === q ? 0 : 1;
    } else {
      if (!words.every((word) => station.haystack.includes(word))) continue;
      if (station.foldedName.startsWith(q)) score = 0;
      else if (` ${station.foldedName}`.includes(` ${first}`)) score = 1;
      else if (station.foldedName.includes(first)) score = 2;
      else score = 3; // matched on town or province only
    }
    scored.push([score, station]);
  }
  scored.sort((a, b) => a[0] - b[0] || a[1].name.localeCompare(b[1].name, 'es'));
  return scored.slice(0, limit).map(([, station]) => station);
}

/** The station's board on ADIF's own site. */
export function stationUrl(code: string): string {
  const normal = normalCode(code);
  return /^\d{5}$/.test(normal) ? `https://info.adif.es/?s=${normal}` : 'https://info.adif.es/';
}
